I have been using the demo.VexRiscvAxi4WithIntegratedJtag with the Git hash: 36b3cd9.
I updated to master and the AXI4 bus is no longer working with the Xilinx IP cores.
The only issue I found was that the dbus ar payload size went from 0x10 (4 bytes per beat) to 0x101 (32 bytes per beat) on a 32 bit/4-byte wide AXI bus.
I am not sure if this is a bug, a changed default value, or AXI4 protocol that Xilinx does not follow.
Thanks for the help.

Here is where that value is assigned in the Verilog.

// Git hash  : 36b3cd918896c94c4e8a224d97c559ab6dbf3ec9
```
  output     [2:0]    dBusAxi_ar_payload_size,
  ...
  assign dBusAxi_ar_payload_size = 3'b010
```  
  
// Git hash  : a4c86130cc4fec7d86052ab9deab90b29c307a1d
```  
  output     [2:0]    dBusAxi_ar_payload_size,
  ...
  assign dBusAxi_ar_payload_size = _zz_dBusAxi_aw_payload_size;
  ...
  assign _zz_dBusAxi_aw_payload_size = ((dBus_cmd_payload_size < _zz__zz_dBusAxi_aw_payload_size) ? _zz__zz_dBusAxi_aw_payload_size_1 : dBus_cmd_payload_size);
  
  assign dBus_cmd_payload_size = dataCache_1_io_mem_cmd_payload_size;
  .io_mem_cmd_payload_size                   (dataCache_1_io_mem_cmd_payload_size            ), //o
  assign io_mem_cmd_payload_size = 3'b101;
  
  assign _zz__zz_dBusAxi_aw_payload_size_1 = {1'd0, _zz_dBusAxi_aw_payload_size_1};
  assign _zz_dBusAxi_aw_payload_size_1 = 2'b10;
```

